<script>
import { Form, Head, Link } from '@inertiajs/vue3';
import PrimaryButton from '@scaffold/components/PrimaryButton.vue';
import { logout } from '@app/routes';
import { send } from '@app/routes/verification';

export default {
    components: { Form, InertiaHead: Head, Link, PrimaryButton },
    props: {
        status: String,
    },
    data() {
        return {
            resendForm: send.form(),
            logoutUrl: logout.url(),
        };
    },
};
</script>

<template>
    <div>
        <InertiaHead title="Apstiprināt e-pasta adresi" />

        <div class="row justify-content-center">
            <div class="lg:col-4 md:col-6 sm:col-8 ms-auto me-auto">
                <div class="card">
                    <div class="card-header card-header-primary text-center">
                        <h1 class="card-title h4">Apstiprināt e-pasta adresi</h1>
                    </div>

                    <div class="card-body text-center">
                        <p>Lai apstiprinātu e-pasta adresi, atveriet saiti, ko nosūtījām uz jūsu e-pastu.</p>
                        <p v-if="status === 'verification-link-sent'" class="text-success" role="status">
                            Nosūtījām jaunu apstiprinājuma saiti uz jūsu e-pasta adresi.
                        </p>

                        <Form v-bind="resendForm" v-slot="{ processing }">
                            <PrimaryButton type="submit" class="btn btn-primary" :disabled="processing">
                                Nosūtīt saiti vēlreiz
                            </PrimaryButton>
                        </Form>
                    </div>

                    <div class="card-footer justify-content-center">
                        <Link :href="logoutUrl" method="post" as="button" class="btn btn-link">Iziet</Link>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
